-- 701: GÖZ MODÜLÜ KİMLİK ÜRETEÇLERİNİ (sequence) TABLOYLA EŞİTLE.
--
-- 697 aynı düzeltmeyi yatan hasta tabloları için yapmıştı; göz tablolarında da
-- aynı durum var: 691 demo/göç satırları kimliği AÇIKÇA vererek yazıldı
-- (`insert ... (id, ...) values (9001, ...)`), bu yüzden `generated by default
-- as identity` üreteci hiç ilerlemedi. Uygulamadan açılan ilk göz cihazı 1,
-- ikincisi 2 ... diye gidiyor ve 9001'e gelindiğinde "duplicate key" ile
-- kayıt açılamaz oluyor — hata, sebebinden aylar sonra çıkıyor.
--
-- TEK TEK TABLO SAYMIYORUZ: göz modülü 25 tablo ve yarısı ölçüm tablosu;
-- listeyi elle tutmak, yeni eklenen tablonun unutulması demek. `goz_` ön ekli
-- bütün tablolar taranır.
--
-- GÜVENLİ: yalnız üreteci ilerletir, satıra dokunmaz; üreteç zaten ileriyse
-- GERİ ÇEKİLMEZ (geri çekmek, mevcut satırlarla çakışan kimlik üretirdi).
-- Tekrar çalıştırılabilir.

do $$
declare
    r      record;
    dizi   text;
    enb    bigint;
    simdi  bigint;
begin
    for r in
        select c.relname as tablo
          from pg_class c
          join pg_namespace n on n.oid = c.relnamespace
         where n.nspname = 'public'
           and c.relkind = 'r'
           and c.relname like 'goz\_%'
           -- `id` KOLONU OLMAYAN TABLO VAR (goz_hasta_ozet: birincil anahtarı
           --   hasta_id). Önce kolonu doğrulamazsak döngü orada patlıyor ve
           --   sonraki tabloların üreteci hiç düzelmiyor.
           and exists (select 1 from pg_attribute a
                        where a.attrelid = c.oid and a.attname = 'id'
                          and a.attnum > 0 and not a.attisdropped)
         order by c.relname
    loop
        dizi := pg_get_serial_sequence('public.' || quote_ident(r.tablo), 'id');
        if dizi is null then continue; end if;

        execute format('select coalesce(max(id), 0) from public.%I', r.tablo) into enb;
        if enb = 0 then continue; end if;

        execute format('select last_value from %s', dizi) into simdi;
        if simdi >= enb then continue; end if;

        perform setval(dizi, enb, true);
        raise notice 'sequence % -> %', dizi, enb;
    end loop;
end $$;
